function tools(){const r=cp.spawnSync('pandoc',['--version'],{encoding:'utf8',timeout:4000});return{pandoc:{status:r.status,error:r.error?.code||null,stdout:r.stdout||'',stderr:r.stderr||''}}}
const base={marker,files,document:{bytes:input.length,sha256:sha(input)},node:process.version,program_sha256:sha(fs.readFileSync(__filename))};
if(process.argv[2]==='before'){const v={...base,tools:tools()};fs.writeFileSync('qa407-before.json',JSON.stringify(v));console.log('QA407_BEFORE '+JSON.stringify(v));process.exit(0)}
function output(b){const text=b.toString('utf8');for(const token of ref.document.required_html)if(!text.includes(token))throw Error('HTML differs');return{...base,tools:tools(),html:{bytes:b.length,sha256:sha(b),text}}}
if(process.argv[2]==='build'){const v={...output(fs.readFileSync('qa407.html')),before:require('./qa407-before.json')};fs.writeFileSync('qa407-build.json',JSON.stringify(v));console.log('QA407_AFTER '+JSON.stringify(v));process.exit(0)}
const built=require('./qa407-build.json');http.createServer((req,res)=>{const b=cp.execFileSync('pandoc',['--from=markdown','--to=html5','--wrap=none','qa407.md'],{timeout:4000}),runtime={...output(b),request_url:req.url},v={build:built,runtime};res.setHeader('Cache-Control','no-store');res.setHeader('Content-Type',req.url.startsWith('/document')?'text/html; charset=utf-8':'application/json');res.end(req.url.startsWith('/document')?b:JSON.stringify(v));if(req.url.includes('qa407='))console.log('QA407_REQUEST '+JSON.stringify(v))}).listen(Number(process.env.PORT||10000),'0.0.0.0',function(){console.log('QA407_READY '+JSON.stringify({port:this.address().port,...base}))});
